+template<typename EntryA, typename EntryB>
+bool same_keys(const EntryA* a, const EntryB* b, std::size_t n)
+{
+    for (std::size_t i = 0; i < n; ++i)
+    {
+        if (!(a[i].first == b[i].first))
+        {
+            return false;
+        }
+    }
+    return true;
